entries[41605] = { ["name"] = "Geweihter Zauberfaden", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 70\nBenötigt Schneiderei (400)\nBenutzen: Bestickt Hosen dauerhaft mit einem Zauberfaden, der die Zaubermacht um 50 und die Willenskraft um 20 erhöht.\n\nDurch diese Verzauberung wird der Gegenstand seelengebunden.\nVerkaufspreis:" }
